import {FormEvent, ReactNode, useCallback, useEffect, useRef, useState} from 'react';
import {Link, useNavigate, useParams, useSearchParams} from 'react-router-dom';
import {Archive, ArrowLeft, ArrowRight, BookOpen, Check, CheckCircle2, ChevronDown, Download, FileText, FlaskConical, GitBranch, History, Link2, MessageSquareText, Paperclip, Plus, RefreshCw, Search, Send, ShieldCheck, Sparkles, Square, Upload, Workflow, X} from 'lucide-react';
